/**
 * Decoder for `.ptp` v2 — the lightweight toolpath artifact generated by
 * procontrol-core for remote clients.
 *
 * Returns the canonical `ParsedGcodeArrays` shape (see `types.ts`), the same
 * struct-of-arrays layout `parser.ts` produces, so either can feed
 * `toLines()` and callers do not need to care which one produced a given
 * model. There is deliberately no `e` field: no renderer reads it, and
 * `isTravel` is stored explicitly rather than derived from it.
 *
 * v2 adds a `layerId` field to each layer-table entry: the source parser's
 * actual point `layer` value, carried verbatim, instead of v1's 0..N-1
 * bucket ordinal. v1 silently drifted from the source whenever the parser's
 * layer ids were not already 0-based and contiguous (a 1-based Simplify3D
 * `; layer N` file, or even the plain Z-change fallback path in general).
 * `layerId` is NOT an index into `layers` — the two are independent notions
 * (see `types.ts`'s `layers` doc) and nothing in this codebase indexes
 * `layers` by a point's `layer`.
 *
 * Format is documented in
 * `docs/superpowers/specs/2026-07-19-gcode-light-preview-design.md` (in
 * ProControlTauri) and implemented on the encoder side in
 * `services/procontrol-core/src/preview/codec.rs`. Any change must land on
 * both sides together, with a version bump.
 */
import type { Bounds, ParsedGcodeArrays } from "./types";

export class PtpDecodeError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PtpDecodeError";
  }
}

const MAGIC = 0x31505450; // "PTP1" little-endian
const VERSION = 2;

const OP_SET_FEATURE = 0x01;
const OP_SET_TOOL = 0x02;
const OP_SET_FEEDRATE = 0x03;
const OP_SET_BEAD = 0x04;
const OP_MOVE_TO = 0x05;
const OP_POLYLINE = 0x06;

const HEADER_LEN = 4 + 2 + 2 + 24 + 4 + 4 + 4;
/** `layerId u32 | zUm u32 | offset u32 | count u32`. */
const LAYER_ENTRY_LEN = 16;

const XY_SCALE = 100; // 0.01 mm
const MICRON_SCALE = 1000; // 0.001 mm

/** Cursor over the byte stream, shared by the varint readers. */
class Reader {
  constructor(
    private readonly bytes: Uint8Array,
    public cursor: number,
  ) {}

  byte(): number {
    if (this.cursor >= this.bytes.length) throw new PtpDecodeError("truncated .ptp data");
    return this.bytes[this.cursor++];
  }

  varint(): number {
    let result = 0;
    let shift = 0;
    for (;;) {
      const b = this.byte();
      result += (b & 0x7f) * Math.pow(2, shift);
      if ((b & 0x80) === 0) return result;
      shift += 7;
      if (shift > 63) throw new PtpDecodeError("varint overflow");
    }
  }

  zigzag(): number {
    const v = this.varint();
    return (v % 2 === 0 ? v : -(v + 1)) / 2;
  }
}

/**
 * Accepts a raw `ArrayBuffer` (the only shape today's one caller,
 * `previewSource.ts`'s `response.arrayBuffer()`, ever produces) or any
 * `ArrayBufferView` (`Uint8Array`, `DataView`, ...). A view's `byteOffset`/
 * `byteLength` are honoured rather than assumed to be 0/the whole buffer, so
 * a future caller can safely hand in a slice of a larger, shared buffer.
 */
export function decodePtp(input: ArrayBuffer | ArrayBufferView): ParsedGcodeArrays {
  // `ArrayBuffer.isView` rather than `input instanceof ArrayBuffer`: the
  // fixture/test buffers here can cross a realm boundary (e.g. a Node
  // `Buffer` read outside jsdom's vm context), where `instanceof` against a
  // differently-realmed `ArrayBuffer` constructor silently returns false.
  const { buffer, byteOffset, byteLength } = ArrayBuffer.isView(input)
    ? input
    : { buffer: input, byteOffset: 0, byteLength: input.byteLength };

  const bytes = new Uint8Array(buffer, byteOffset, byteLength);
  if (bytes.length < HEADER_LEN) throw new PtpDecodeError("truncated .ptp data");

  const view = new DataView(buffer, byteOffset, byteLength);
  if (view.getUint32(0, true) !== MAGIC) throw new PtpDecodeError("not a .ptp file");

  const version = view.getUint16(4, true);
  if (version !== VERSION) throw new PtpDecodeError(`unsupported .ptp version ${version}`);

  const bounds: Bounds = {
    minX: view.getFloat32(8, true),
    maxX: view.getFloat32(12, true),
    minY: view.getFloat32(16, true),
    maxY: view.getFloat32(20, true),
    minZ: view.getFloat32(24, true),
    maxZ: view.getFloat32(28, true),
  };
  const layerCount = view.getUint32(32, true);
  const pointCount = view.getUint32(36, true);
  const layerZCount = view.getUint32(40, true);

  // The layers array is carried verbatim from the parser rather than derived
  // from point Z: on the `;LAYER_CHANGE` path the two disagree by one layer,
  // and `ParsedGcodeArrays.layers` must match what the local parser produces.
  //
  // `layerZCount` and `layerCount` are untrusted (straight off the wire).
  // Rather than looping a hostile count times, each is turned into an end
  // offset first (multiplying by the element's wire size) and checked
  // against the buffer's actual length — equivalent to clamping the count by
  // capacity / element size, but expressed the way the loop bound is used —
  // so a huge count fails this check before any loop runs.
  const layersEnd = HEADER_LEN + layerZCount * 4;
  if (bytes.length < layersEnd) throw new PtpDecodeError("truncated .ptp layer Z array");
  const layers: number[] = [];
  for (let i = 0; i < layerZCount; i++) {
    layers.push(view.getUint32(HEADER_LEN + i * 4, true) / MICRON_SCALE);
  }

  const tableEnd = layersEnd + layerCount * LAYER_ENTRY_LEN;
  if (bytes.length < tableEnd) throw new PtpDecodeError("truncated .ptp layer table");

  const table: Array<{ layerId: number; zUm: number; offset: number; count: number }> = [];
  // A well-formed encoder never emits two entries for the same layer id
  // (the Rust side's `BTreeMap` keys are unique by construction), so a
  // repeat can only come from a corrupted or hostile stream — reject it
  // rather than silently giving two different Z values to "the same" layer.
  const seenLayerIds = new Set<number>();
  for (let i = 0; i < layerCount; i++) {
    const base = layersEnd + i * LAYER_ENTRY_LEN;
    const layerId = view.getUint32(base, true);
    if (seenLayerIds.has(layerId)) {
      throw new PtpDecodeError(`duplicate layer id ${layerId} in layer table`);
    }
    seenLayerIds.add(layerId);
    table.push({
      layerId,
      zUm: view.getUint32(base + 4, true),
      offset: view.getUint32(base + 8, true),
      count: view.getUint32(base + 12, true),
    });
  }

  const streamBase = tableEnd;

  // `pointCount` is untrusted too, and unlike the arrays above it now backs
  // an eager allocation: `new Float32Array(n)` reserves `n * 4` bytes
  // immediately, unlike the sparse `new Array(n)` the original decoder used.
  // Clamp it against the cheapest possible per-point wire cost (1 byte —
  // a single input byte can never decode into more than one point) before
  // allocating, so a tiny hostile buffer can't claim a multi-gigabyte
  // pointCount and OOM the process.
  const remainingStreamBytes = bytes.length - streamBase;
  if (pointCount > remainingStreamBytes) throw new PtpDecodeError("truncated .ptp point stream");

  const xs = new Float32Array(pointCount);
  const ys = new Float32Array(pointCount);
  const zs = new Float32Array(pointCount);
  const layerOut = new Uint32Array(pointCount);
  const featureTypeOut = new Uint8Array(pointCount);
  const toolOut = new Uint8Array(pointCount);
  const isTravelOut = new Uint8Array(pointCount);
  const feedrateOut = new Float32Array(pointCount);
  const widthOut = new Float32Array(pointCount);
  const heightOut = new Float32Array(pointCount);
  let written = 0;

  for (let tableIdx = 0; tableIdx < table.length; tableIdx++) {
    const { layerId, zUm, offset, count } = table[tableIdx];
    const z = zUm / MICRON_SCALE;

    // Each layer re-emits its SET_* opcodes and starts from an absolute
    // coordinate, so decoding can begin at any layer's offset.
    const r = new Reader(bytes, streamBase + offset);
    let featureType = 0;
    let tool = 0;
    let feedrate = 0;
    let width = 0;
    let height = 0;
    let x = 0;
    let y = 0;
    let emitted = 0;

    while (emitted < count) {
      const op = r.byte();
      switch (op) {
        case OP_SET_FEATURE:
          featureType = r.byte();
          break;
        case OP_SET_TOOL:
          tool = r.byte();
          break;
        case OP_SET_FEEDRATE:
          feedrate = r.varint();
          break;
        case OP_SET_BEAD: {
          const w = r.byte() | (r.byte() << 8);
          const h = r.byte() | (r.byte() << 8);
          width = w / MICRON_SCALE;
          height = h / MICRON_SCALE;
          break;
        }
        case OP_MOVE_TO:
        case OP_POLYLINE: {
          const n = op === OP_MOVE_TO ? 1 : r.varint();
          const isTravel = op === OP_MOVE_TO;
          for (let k = 0; k < n; k++) {
            x += r.zigzag();
            y += r.zigzag();
            if (written < pointCount) {
              xs[written] = x / XY_SCALE;
              ys[written] = y / XY_SCALE;
              zs[written] = z;
              isTravelOut[written] = isTravel ? 1 : 0;
              layerOut[written] = layerId;
              toolOut[written] = tool;
              feedrateOut[written] = feedrate;
              featureTypeOut[written] = featureType;
              widthOut[written] = width;
              heightOut[written] = height;
            }
            written++;
            emitted++;
          }
          break;
        }
        default:
          throw new PtpDecodeError(`unknown opcode 0x${op.toString(16)}`);
      }
    }
  }

  if (written !== pointCount) {
    throw new PtpDecodeError(`expected ${pointCount} points, decoded ${written}`);
  }

  return {
    xs, ys, zs,
    layer: layerOut,
    featureType: featureTypeOut,
    tool: toolOut,
    isTravel: isTravelOut,
    feedrate: feedrateOut,
    width: widthOut,
    height: heightOut,
    count: pointCount,
    layers,
    bounds,
  };
}
